ALTER TABLE public.op_maintenance_orders ADD COLUMN scheduled_date date, ADD COLUMN materials jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN awaiting_material boolean NOT NULL DEFAULT false; COMMENT ON COLUMN public.op_maintenance_orders.materials IS 'Required materials for this maintenance order: name, quantity and purchased flag'; COMMENT ON COLUMN public.op_maintenance_orders.scheduled_date IS 'Planned service day; null means awaiting distribution';